kubernetes.probes:
startupProbe:            # slow start is not failure; stops restart loops on boot
  httpGet: { path: /health, port: 8000 }
  failureThreshold: 30
  periodSeconds: 2
livenessProbe:           # restarts the pod; must NOT depend on the database
  httpGet: { path: /health, port: 8000 }
readinessProbe:          # removes pod from the Service; SHOULD depend on the database
  httpGet: { path: /ready, port: 8000 }
